export function getPhaseOneCommon(locale: PhaseOneLocale) { return common[locale]; }

export function createPhaseOneDictionary(locale: PhaseOneLocale, englishSource: LocaleDictionary): LocaleDictionary {
  const text = core[locale];
  const ui = common[locale];
  const copy = phrases[locale];
  const localizedOptions: Record<string, Record<string, string>> = {
    none: { es: "Excluir ambas fechas", "pt-br": "Excluir as duas datas", de: "Beide Tage ausschließen", fr: "Exclure les deux dates", vi: "Không tính hai ngày", id: "Kecualikan kedua tanggal", th: "ไม่รวมทั้งสองวัน", "zh-tw": "不包含起訖日", it: "Escludi entrambe le date", nl: "Beide datums uitsluiten", hi: "दोनों तिथियाँ शामिल न करें" },
    start: { es: "Incluir la fecha inicial", "pt-br": "Incluir a data inicial", de: "Startdatum einschließen", fr: "Inclure la date de début", vi: "Tính ngày bắt đầu", id: "Sertakan tanggal mulai", th: "รวมวันเริ่มต้น", "zh-tw": "包含開始日期", it: "Includi la data iniziale", nl: "Begindatum meetellen", hi: "आरंभ तिथि शामिल करें" },
    end: { es: "Incluir la fecha final", "pt-br": "Incluir a data final", de: "Enddatum einschließen", fr: "Inclure la date de fin", vi: "Tính ngày kết thúc", id: "Sertakan tanggal akhir", th: "รวมวันสิ้นสุด", "zh-tw": "包含結束日期", it: "Includi la data finale", nl: "Einddatum meetellen", hi: "अंतिम तिथि शामिल करें" },
    both: { es: "Incluir ambas fechas", "pt-br": "Incluir as duas datas", de: "Beide Tage einschließen", fr: "Inclure les deux dates", vi: "Tính cả hai ngày", id: "Sertakan kedua tanggal", th: "รวมทั้งสองวัน", "zh-tw": "包含起訖兩日", it: "Includi entrambe le date", nl: "Beide datums meetellen", hi: "दोनों तिथियाँ शामिल करें" },
  };
  const frequencyNames: Record<PhaseOneLocale, (count: string) => string> = {
    es: (count) => `${count} vez${count === "1" ? "" : "es"} al año`, "pt-br": (count) => `${count} vez${count === "1" ? "" : "es"} ao ano`, de: (count) => `${count} ${count === "1" ? "Mal" : "Mal pro Jahr"}`, fr: (count) => `${count} fois par an`, vi: (count) => `${count} lần mỗi năm`, id: (count) => `${count} kali per tahun`, th: (count) => `ปีละ ${count} ครั้ง`, "zh-tw": (count) => `每年 ${count} 次`, it: (count) => `${count} volta${count === "1" ? "" : "e"} l’anno`, nl: (count) => `${count} keer per jaar`, hi: (count) => `वर्ष में ${count} बार`,
  };
  const calculators = Object.fromEntries(phaseOneTranslatedCalculatorSlugs.map((slug) => {
    const source = getCalculatorPage(slug);
    if (!source) throw new Error(`Phase 1 translation references unpublished calculator: ${slug}`);
    const name = pageNames[locale][slug];
    const description = pageSummary[locale][slug];
    const enFields = englishSource.calculators[slug]?.fields ?? {};
    const fieldMap = fieldLabels[locale];
    const units: Record<string, Record<PhaseOneLocale, string>> = {
      years: { es: "años", "pt-br": "anos", de: "Jahre", fr: "ans", vi: "năm", id: "tahun", th: "ปี", "zh-tw": "年", it: "anni", nl: "jaar", hi: "वर्ष" },
      days: { es: "días", "pt-br": "dias", de: "Tage", fr: "jours", vi: "ngày", id: "hari", th: "วัน", "zh-tw": "天", it: "giorni", nl: "dagen", hi: "दिन" },
      months: { es: "meses", "pt-br": "meses", de: "Monate", fr: "mois", vi: "tháng", id: "bulan", th: "เดือน", "zh-tw": "個月", it: "mesi", nl: "maanden", hi: "महीने" },
      month: { es: "mes", "pt-br": "mês", de: "Monat", fr: "mois", vi: "tháng", id: "bulan", th: "เดือน", "zh-tw": "個月", it: "mese", nl: "maand", hi: "महीना" },
      servings: { es: "porciones", "pt-br": "porções", de: "Portionen", fr: "portions", vi: "khẩu phần", id: "porsi", th: "หน่วยบริโภค", "zh-tw": "份", it: "porzioni", nl: "porties", hi: "सर्विंग" },
      calories: { es: "kcal", "pt-br": "kcal", de: "kcal", fr: "kcal", vi: "kcal", id: "kkal", th: "กิโลแคลอรี", "zh-tw": "大卡", it: "kcal", nl: "kcal", hi: "किलो कैलोरी" },
      cm: { es: "cm", "pt-br": "cm", de: "cm", fr: "cm", vi: "cm", id: "cm", th: "ซม.", "zh-tw": "公分", it: "cm", nl: "cm", hi: "सेमी" },
      kg: { es: "kg", "pt-br": "kg", de: "kg", fr: "kg", vi: "kg", id: "kg", th: "กก.", "zh-tw": "公斤", it: "kg", nl: "kg", hi: "किग्रा" },
    };
    const fields = Object.fromEntries(Object.entries(enFields).map(([key, field], index) => [key, {
      ...field,
      label: fieldMap[key] ?? `${ui.input} ${index + 1}`,
      ...(field.unit ? { unit: units[field.unit.toLowerCase()]?.[locale] ?? field.unit } : {}),
      ...(field.placeholder ? { placeholder: locale === "th" ? "กรอกค่า" : locale === "hi" ? "मान दर्ज करें" : ui.input } : {}),
    }]));
    const resultMap = resultLabels[locale][slug];
    const englishResults = Object.keys(englishSource.calculators[slug]?.resultLabels ?? {});
    const labels = Object.fromEntries(englishResults.map((key, index) => [key, resultMap[index] ?? `${ui.result} ${index + 1}`]));
    return [slug, {
      name,
      shortName: name,
      title: name,
      description,
      keywords: [name, ...name.split(/\s+/)],
      howTo: copy.guide,
      formula: `${formulaLead[locale]}${formulaBySlug[slug]}`,
      example: { question: copy.exampleQ.replace("{name}", name), answer: copy.exampleA },
      faqs: [
        { question: copy.faqQ.replace("{name}", name), answer: copy.faqA },
        { question: copy.faqQ2, answer: copy.faqA2 },
      ],
      related: source.relatedCalculatorIds.filter((related) => phaseOneTranslatedCalculatorSlugs.includes(related as (typeof phaseOneTranslatedCalculatorSlugs)[number])) as LocalizedCalculatorContent["related"],
      fields,
      options: Object.fromEntries(Object.entries(englishSource.calculators[slug]?.options ?? {}).map(([key, values]) => [key, Object.fromEntries(Object.entries(values).map(([value]) => [value, localizedOptions[value]?.[locale] ?? (key === "frequency" ? frequencyNames[locale](value) : ui.input)]))])),
      resultLabels: labels,
      validation: copy.validation,
      resultNote: copy.note,
    } satisfies LocalizedCalculatorContent];
  }));

  return {
    locale,
    siteName: text.site,
    description: text.description,
    common: ui,
    nav: { home: text.home, calculators: text.calculators, menu: text.menu, search: ui.search, close: locale === "es" ? "Cerrar" : locale === "pt-br" ? "Fechar" : locale === "de" ? "Schließen" : locale === "fr" ? "Fermer" : locale === "vi" ? "Đóng" : locale === "id" ? "Tutup" : locale === "th" ? "ปิด" : locale === "zh-tw" ? "關閉" : locale === "it" ? "Chiudi" : locale === "nl" ? "Sluiten" : "बंद करें", searchEmpty: text.searchEmpty, language: locale === "es" ? "Idioma" : locale === "pt-br" ? "Idioma" : locale === "de" ? "Sprache" : locale === "fr" ? "Langue" : locale === "vi" ? "Ngôn ngữ" : locale === "id" ? "Bahasa" : locale === "th" ? "ภาษา" : locale === "zh-tw" ? "語言" : locale === "it" ? "Lingua" : locale === "nl" ? "Taal" : "भाषा", skip: text.skip },
    categories: text.categories,
    calculatorList: { title: text.listTitle, description: text.listDescription, breadcrumbHome: text.home, breadcrumbCalculators: text.calculators, count: "", noResults: ui.noResults },
    detail: { home: text.home, calculators: text.calculators, howTo: text.howTo, formula: ui.formula, example: ui.example, notes: text.notes, faqs: ui.faq, related: ui.relatedCalculators, result: ui.result, calculate: ui.calculate, invalid: ui.invalidInput, updated: text.updated },
    home: { title: text.homeTitle, description: text.description, featured: ui.category, categories: ui.category },
    units: { won: "KRW", number: ui.input, year: ({ es: "años", "pt-br": "anos", de: "Jahre", fr: "ans", vi: "năm", id: "tahun", th: "ปี", "zh-tw": "年", it: "anni", nl: "jaar", hi: "वर्ष" })[locale], month: ({ es: "meses", "pt-br": "meses", de: "Monate", fr: "mois", vi: "tháng", id: "bulan", th: "เดือน", "zh-tw": "個月", it: "mesi", nl: "maanden", hi: "महीने" })[locale], durationLabel: ({ es: "Duración", "pt-br": "Duração", de: "Laufzeit", fr: "Durée", vi: "Thời hạn", id: "Durasi", th: "ระยะเวลา", "zh-tw": "期間", it: "Durata", nl: "Looptijd", hi: "अवधि" })[locale] },
    categoriesOrder: calculatorCategoryOrder,
    calculators: calculators as LocaleDictionary["calculators"],
  };
}

export function phaseOneLocaleDictionary(locale: Locale, englishSource: LocaleDictionary) {
  return locale === "es" || locale === "pt-br" || locale === "de" || locale === "fr" || locale === "vi" || locale === "id" || locale === "th" || locale === "zh-tw" || locale === "it" || locale === "nl" || locale === "hi" ? createPhaseOneDictionary(locale, englishSource) : undefined;
}

export function phaseOneAvailableSlugs(locale: Locale) { return localizedIndexSlugs(locale).filter((slug) => phaseOneTranslatedCalculatorSlugs.includes(slug as (typeof phaseOneTranslatedCalculatorSlugs)[number])); }
